-- 029: 사용자에게 보이는 장소 메모·지역 이름에서 가운데점(U+00B7) 걷어내기
--
-- 아직 실행하지 않은 검토용 마이그레이션이다. 운영 DB에는 검토 후 직접 적용한다.
--
-- 1) 메모(locations.memo 건, attractions.memo 건)
--    "분위기: 아늑한·조용한. 맛: 고소한·달콤한·산미 있는. 데이트·혼밥 방문 많음" 같은 압축 나열을
--    "분위기: 아늑하고 조용함. 맛: 고소하고 달콤하며 산미 있음. 많이 찾는 때: 데이트, 혼밥"처럼 바꾼다.
--    단어는 그대로 두고 활용 어미와 구조만 바꾼다 (사실을 더하거나 빼지 않는다).
--    각 UPDATE는 원문이 그대로일 때만 바뀐다 — 그사이 누가 메모를 고쳤으면 그 행은 건너뛴다.
--    생성: scratchpad memo_fix.py (규칙: 관형형 형용사만 활용, 명사는 그대로, 끝이 아닌 명사 뒤는 쉼표)
--
-- 2) 지역 이름(places.region 종, 트리거로 locations/attractions에 동기화)
--    "관악구 · 봉천" → "관악구 봉천", "의정부 · 의정부" → "의정부"
--    아직 고르지 않은 검토함(place_intake.region_hint)도 같은 규칙으로 맞춘다.
--    앞으로 들어오는 지역 이름은 admin/scripts/odiga-vault-intake.mjs가 공백으로 잇는다.

BEGIN;

UPDATE places
SET region = CASE
  WHEN split_part(region, ' · ', 1) = split_part(region, ' · ', 2) THEN split_part(region, ' · ', 1)
  ELSE replace(region, ' · ', ' ')
END
WHERE region LIKE '% · %';

UPDATE place_intake
SET region_hint = CASE
  WHEN split_part(region_hint, ' · ', 1) = split_part(region_hint, ' · ', 2) THEN split_part(region_hint, ' · ', 1)
  ELSE replace(region_hint, ' · ', ' ')
END
WHERE region_hint LIKE '% · %';

