WHERE id = '487cd3a2-2b29-4379-b4b3-6bcbea3549d1' AND memo = $m$주차장 없음. 페퍼로니 피자 추천, 프라이빗룸. 분위기: 레트로한·힙한·빈티지 감성. 맛: 치즈가 풍부한·달달한·짭짤한. 데이트·단체 모임 방문 많음$m$;

